\title{Factorization of the Cyclotomic Gauss-Sum Matrix}
\author{Aristotle}
\date{2026-07-13}

\begin{document}
\maketitle

\begin{abstract}
We study the $n \times n$ \emph{cyclotomic Gauss-sum matrix}
$A_k(\chi) = \big[\,G_N(\chi^{k(i+j)})\,\big]_{0 \le i,j < n}$, whose entries are
Gauss sums over $\Z/N\Z$ with $N = p^m$ a prime power and $n = \varphi(N)/k$.
Because a Gauss sum is the finite Fourier transform of the corresponding
\emph{Gauss periods} $\eta_a$, the matrix admits a spectral-type factorization
$A = W D W^{\T}$, where $W_{i,a} = \omega^{ai}$ is the discrete Fourier transform
(Vandermonde) matrix in a primitive $n$-th root of unity $\omega$, and
$D = \diag(\eta_0,\dots,\eta_{n-1})$ is the diagonal matrix of periods. We isolate
the linear-algebraic core of this statement over an arbitrary commutative ring,
taking the Fourier--period identity as the definition of the entries, and derive:
symmetry of $W$ and $A$; the Vandermonde determinant of $W$;
$\det A = (\det W)^2 \prod_a \eta_a$; an invertibility criterion over a field;
the discrete Fourier orthogonality relation
$(W^{\T}W)_{a,b} = n\,[\,n \mid a+b\,]$; and recovery of the Gauss periods from a
single column of $A$ by the inverse transform. We refute the tempting conjecture
$W^{\T}W = nI$: the correct identity is $W^{\T}W = nP$, where $P$ is the reversal
permutation $a \mapsto (n-a)\bmod n$, which differs from the identity for all
$n \ge 3$.
\end{abstract}

\section{Introduction}

Gauss sums encode delicate arithmetic information about characters modulo $N$.
Assembling a family of Gauss sums into a matrix exposes relationships among them.
The object of interest is the cyclotomic Gauss-sum matrix
\[
A_k(\chi) = \big[\,G_N(\chi^{k(i+j)})\,\big]_{0 \le i,j < n},
\qquad N = p^m, \quad n = \varphi(N)/k,
\]
where $\chi$ is a multiplicative character and $G_N$ a Gauss sum. Each entry
depends only on $i+j$, so the matrix is symmetric and Hankel-like, and one expects
the discrete Fourier transform to diagonalize it.

The key structural fact is that a Gauss sum is the finite Fourier transform of the
\emph{Gauss periods} of the $k$-th power residue cyclotomic cosets:
\begin{equation}
G_N(\chi^{ks}) = \sum_{a=0}^{n-1} \eta_a\, \omega^{as}, \tag{$\star$}
\end{equation}
with $\omega$ a primitive $n$-th root of unity. We take $(\star)$ as the
\emph{definition} of the matrix entries and develop the resulting linear algebra
over an arbitrary commutative ring $R$, obtaining a self-contained account of the
factorization and its corollaries.

\section{Definitions}

Let $R$ be a commutative ring, $n \ge 1$, and $\omega \in R$ (a primitive $n$-th
root of unity where noted). Rows and columns are indexed by $\{0,\dots,n-1\}$.

\begin{definition}[Fourier / Vandermonde matrix]
The discrete Fourier transform matrix $W = W_n(\omega)$ has entries
$W_{i,a} = \omega^{a i}$.
\end{definition}

\begin{definition}[Diagonal period matrix]
Given $\eta = (\eta_0,\dots,\eta_{n-1}) \in R^n$, let
$D = \diag(\eta_0,\dots,\eta_{n-1})$.
\end{definition}

\begin{definition}[Cyclotomic Gauss-sum matrix]
The Gauss-sum matrix $A = A_n(\omega,\eta)$ has entries
\[
A_{i,j} = \sum_{a=0}^{n-1} \eta_a\, \omega^{a(i+j)}.
\]
In the number-theoretic model, $\eta_a$ is the Gauss period of the $a$-th coset,
$\omega$ is a primitive $n$-th root of unity, and $A_{i,j} = G_N(\chi^{k(i+j)})$.
\end{definition}

\begin{remark}
Each entry of $A$ is the finite Fourier transform of the period vector evaluated
at frequency $i+j$. All results below follow from this generating identity.
\end{remark}

\section{The factorization}

\begin{proposition}[Symmetry of $W$]
$W^{\T} = W$.
\end{proposition}
\begin{proof}
$(W^{\T})_{i,a} = W_{a,i} = \omega^{ia} = \omega^{ai} = W_{i,a}$.
\end{proof}

\begin{proposition}[Symmetry of $A$]
$A^{\T} = A$.
\end{proposition}
\begin{proof}
$A_{j,i} = \sum_a \eta_a \omega^{a(j+i)} = \sum_a \eta_a \omega^{a(i+j)} = A_{i,j}$.
\end{proof}

\begin{theorem}[Factorization]
$A = W\,D\,W^{\T}$.
\end{theorem}
\begin{proof}
Since $D$ is diagonal, $(WD)_{i,a} = \eta_a \omega^{ai}$, so
\[
(W D W^{\T})_{i,j} = \sum_{a} \eta_a \omega^{ai} \omega^{aj}
= \sum_a \eta_a \omega^{a(i+j)} = A_{i,j},
\]
using $\omega^{ai}\omega^{aj} = \omega^{a(i+j)}$ and $a(i+j) = ai + aj$.
\end{proof}

Because $W$ is symmetric, $A = W D W$ exhibits $A$ as a conjugate of the diagonal
period matrix by the Fourier transform.

\section{Determinant and invertibility}

\begin{proposition}[$W$ is Vandermonde]
$W$ is the Vandermonde matrix in the nodes $x_i = \omega^{i}$, i.e.
$W_{i,a} = (\omega^{i})^{a}$.
\end{proposition}

\begin{proposition}[Vandermonde determinant]
\[
\det W = \prod_{0 \le i < j < n} \big(\omega^{j} - \omega^{i}\big).
\]
\end{proposition}
\begin{proof}
Apply the classical Vandermonde determinant to the nodes
$\omega^0,\dots,\omega^{n-1}$.
\end{proof}

\begin{theorem}[Determinant of $A$]
\[
\det A = (\det W)^2 \cdot \prod_{a=0}^{n-1} \eta_a.
\]
\end{theorem}
\begin{proof}
$\det A = \det W \cdot \det D \cdot \det W^{\T}$ with $\det W^{\T} = \det W$ and
$\det D = \prod_a \eta_a$.
\end{proof}

\begin{theorem}[Invertibility criterion]
Over a field $K$,
\[
\det A \ne 0 \iff \det W \ne 0 \ \text{ and } \ \eta_a \ne 0 \text{ for all } a.
\]
\end{theorem}
\begin{proof}
In a field a product is nonzero iff each factor is nonzero; apply to
$\det A = (\det W)^2 \prod_a \eta_a$.
\end{proof}

By the Vandermonde determinant, $\det W \ne 0$ is equivalent to distinctness of
the nodes $\omega^i$, which holds exactly when $\omega$ is primitive.

\section{Orthogonality, inversion, and a refuted conjecture}

Assume $K$ is a field and $\omega$ a primitive $n$-th root of unity.

\begin{lemma}[Geometric sum over roots of unity]
If $r^n = 1$ then $\sum_{i=0}^{n-1} r^i = n$ if $r=1$, and $0$ otherwise.
\end{lemma}
\begin{proof}
If $r = 1$ the sum is $n$; otherwise $\sum_i r^i = (r^n-1)/(r-1) = 0$.
\end{proof}

\begin{theorem}[Discrete Fourier orthogonality]
For all $a,b$,
\[
(W^{\T} W)_{a,b} = \begin{cases} n & n \mid a+b,\\ 0 & \text{otherwise.}\end{cases}
\]
\end{theorem}
\begin{proof}
$(W^{\T}W)_{a,b} = \sum_i \omega^{ai}\omega^{bi} = \sum_i (\omega^{a+b})^i$. With
$r = \omega^{a+b}$ we have $r^n = 1$, and $r=1 \iff n \mid a+b$. Apply the lemma.
\end{proof}

\begin{corollary}[Reversal structure]
Since $0 \le a,b < n$, we have $n \mid a+b$ iff $b \equiv -a \pmod n$. Hence
$W^{\T}W = n P$, where $P$ is the reversal permutation $a \mapsto (n-a)\bmod n$.
\end{corollary}

\begin{theorem}[Character orthogonality, inverse form]
For all $a,c$,
\[
\sum_{i=0}^{n-1} (\omega^{ci})^{-1} \omega^{ai}
= \begin{cases} n & a = c,\\ 0 & a \ne c.\end{cases}
\]
\end{theorem}
\begin{proof}
The summand is $(\omega^a (\omega^c)^{-1})^i$; with $r = \omega^a(\omega^c)^{-1}$
we have $r^n = 1$ and $r = 1 \iff a = c$. Apply the lemma.
\end{proof}

\begin{theorem}[Fourier inversion / period recovery]
For every $c$,
\[
\sum_{i=0}^{n-1} (\omega^{ci})^{-1}\Big(\sum_{a=0}^{n-1}\eta_a \omega^{ai}\Big)
= n\,\eta_c,
\qquad\text{and}\qquad
\sum_{i=0}^{n-1} (\omega^{ci})^{-1} A_{i,0} = n\,\eta_c.
\]
\end{theorem}
\begin{proof}
Exchange summation order:
$\sum_i (\omega^{ci})^{-1}\sum_a \eta_a\omega^{ai}
= \sum_a \eta_a \sum_i (\omega^{ci})^{-1}\omega^{ai} = \sum_a \eta_a\,n[a=c]
= n\eta_c$. Since $A_{i,0} = \sum_a \eta_a \omega^{ai}$, the second identity
follows.
\end{proof}

\begin{theorem}[Refutation of $W^{\T}W = nI$]
If $n \ge 3$ and $n \ne 0$ in $K$, then $W^{\T}W \ne nI$.
\end{theorem}
\begin{proof}
At $(a,b) = (1,n-1)$ we have $a+b = n$, so $(W^{\T}W)_{1,n-1} = n \ne 0$ by the
orthogonality theorem, whereas $(nI)_{1,n-1} = 0$ since $1 \ne n-1$ for $n \ge 3$.
\end{proof}

By the corollary, the correct identity is $W^{\T}W = nP$ with $P$ the reversal
permutation; it collapses to $nI$ only for $n \le 2$.

\section{Algorithms}

\textbf{Assemble $A$.} Precompute $\omega^0,\dots,\omega^{2n-2}$ and fill
$A_{i,j} = \sum_a \eta_a \omega^{a(i+j)}$; cost $O(n^3)$ naïvely, $O(n^2 \log n)$
with an FFT.

\textbf{Recover periods.} $\eta_c = \frac1n \sum_i (\omega^{ci})^{-1} A_{i,0}$;
cost $O(n^2)$ directly, $O(n \log n)$ with an FFT.

\textbf{Determinant / invertibility.}
$\det A = \big(\prod_{i<j}(\omega^j - \omega^i)\big)^2 \prod_a \eta_a$;
cost $O(n^2)$.

\section{Discussion}

The factorization instantiates the principle ``diagonalize by Fourier'' for
Hankel-type matrices, connecting classical number theory to FFT-based
computational linear algebra. The determinant reduces to a Vandermonde square
(related to the discriminant of $x^n-1$) times the product of periods.
Invertibility fails exactly when a Gauss period vanishes. The refuted conjecture
$W^{\T}W = nI$ illustrates the value of a contrarian check: the true orthogonality
pairs each frequency with its mirror, and this subtlety is what makes inversion
consistent.

\section{Future directions}

\begin{enumerate}
\item \textbf{Bridge to genuine Gauss sums.} Replace abstract entries by
$G_N(\chi^{ks})$ over $\Z/N\Z$ and prove
$G_N(\chi^{ks}) = \sum_a \eta_a \omega^{as}$, specializing the factorization to
$A_k(\chi) = [G_N(\chi^{k(i+j)})]$.
\item \textbf{Reversal permutation, explicitly.} Package orthogonality as
$W^{\T}W = n P$ and deduce
$A^{-1} = \tfrac{1}{n^2} W^{\T} P D^{-1} P W$ over a field with $n$ invertible and
all $\eta_a \ne 0$.
\item \textbf{Eigenstructure.} Interpret $A = W D W$ as a spectral-type
decomposition; extract $\tr A = \sum_a \eta_a(\sum_i \omega^{2ai})$.
\item \textbf{Prime-power moduli.} Instantiate with $N = p^m$, $n = \varphi(N)/k$,
tying $\eta$ to the period polynomials of the cyclotomic cosets.
\item \textbf{Determinant as a discriminant.} Relate $(\det W)^2$ to the
discriminant of $x^n - 1$.
\end{enumerate}

\section{Conclusion}

Taking the Fourier--period identity as the definition of its entries, the
cyclotomic Gauss-sum matrix factors as $A = W D W^{\T}$, a conjugation of the
diagonal period matrix by the discrete Fourier transform. From this decomposition
flow the symmetry of $A$, its determinant $(\det W)^2 \prod_a \eta_a$, a sharp
invertibility criterion, recovery of the periods by inverse DFT, and the corrected
orthogonality relation $W^{\T}W = nP$.

\end{document}

