"""Verify the factorization A = W D W^T for the cyclotomic Gauss-sum matrix."""
from __future__ import annotations
import cmath, math
from typing import List

Matrix = List[List[complex]]


def primitive_root(n: int) -> complex:
    return cmath.exp(2j * math.pi / n)


def W_matrix(n: int, omega: complex) -> Matrix:
    return [[omega ** (a * i) for a in range(n)] for i in range(n)]


def A_matrix(n: int, omega: complex, eta: List[complex]) -> Matrix:
    return [[sum(eta[a] * omega ** (a * (i + j)) for a in range(n))
             for j in range(n)] for i in range(n)]


def transpose(M: Matrix) -> Matrix:
    return [list(r) for r in zip(*M)]


def matmul(X: Matrix, Y: Matrix) -> Matrix:
    return [[sum(X[i][k] * Y[k][j] for k in range(len(Y)))
             for j in range(len(Y[0]))] for i in range(len(X))]


def verify(n: int, eta: List[complex]) -> float:
    omega = primitive_root(n)
    W = W_matrix(n, omega)
    D = [[eta[i] if i == j else 0j for j in range(n)] for i in range(n)]
    A = A_matrix(n, omega, eta)
    WDWt = matmul(matmul(W, D), transpose(W))
    return max(abs(A[i][j] - WDWt[i][j]) for i in range(n) for j in range(n))


if __name__ == "__main__":
    for n in (3, 5, 7, 12):
        eta = [float((a * a) % (n + 1) + 1) + 0j for a in range(n)]
        print(f"n = {n:2d}:  max |A - W D W^T| = {verify(n, eta):.2e}")

"""Illustrate W^T W = n P (reversal permutation), refuting W^T W = n I."""
from __future__ import annotations
import cmath, math
from typing import List

Matrix = List[List[complex]]


def primitive_root(n: int) -> complex:
    return cmath.exp(2j * math.pi / n)


def W_matrix(n: int, omega: complex) -> Matrix:
    return [[omega ** (a * i) for a in range(n)] for i in range(n)]


def gram(n: int) -> Matrix:
    omega = primitive_root(n)
    W = W_matrix(n, omega)
    Wt = [list(r) for r in zip(*W)]
    return [[sum(Wt[a][k] * W[k][b] for k in range(n))
             for b in range(n)] for a in range(n)]


if __name__ == "__main__":
    for n in (2, 3, 5):
        G = gram(n)
        rounded = [[round(G[a][b].real) for b in range(n)] for a in range(n)]
        is_identity = all(
            abs(G[a][b] - (n if a == b else 0)) < 1e-9
            for a in range(n) for b in range(n)
        )
        print(f"n = {n}:  W^T W / n has support on a -> (n-a) mod n")
        for row in rounded:
            print("   ", row)
        print(f"   equals n*I?  {is_identity}\n")

