function ASSEMBLE(eta[0..n-1], omega):
    for i in 0..n-1:
        for j in 0..n-1:
            A[i][j] <- 0
            for a in 0..n-1:
                A[i][j] <- A[i][j] + eta[a] * omega^(a*(i+j))
    return A

function RECOVER(column0[0..n-1], omega):
    for c in 0..n-1:
        acc <- 0
        for i in 0..n-1:
            acc <- acc + (omega^(c*i))^{-1} * column0[i]
        eta[c] <- acc / n
    return eta

function DET(nodes[0..n-1], eta[0..n-1]):
    vander <- 1
    for i in 0..n-1:
        for j in i+1..n-1:
            vander <- vander * (nodes[j] - nodes[i])
    return vander^2 * product(eta)

function INVERTIBLE(nodes, eta):
    return ALL_DISTINCT(nodes) and ALL_NONZERO(eta)
